using FreshFoundation;
using System.Text.Json;
internal static class ProviderChecks
{
    public static int Run()
    {
        var checks=new List<object>();int failures=0;void Assert(bool value){if(!value)throw new Exception("Synthetic provider assertion failed");}void Test(string name,Action run){try{run();checks.Add(new{name,status="PASS"});}catch(Exception e){failures++;checks.Add(new{name,status="FAIL",error=e.Message});}}
        GameCatalog Make(string label,uint id=0x04000031)=>new([new(GameCatalogKind.Item,id,new(){["en"]=label,["zh-CN"]="合成"+label},Origin:new("SYNTHETIC source","CC0 synthetic labels","SYNTHETIC edition"),DeclaredStatus:CatalogItemStatus.VERIFIED_ITEM,DeclaredMaximumQuantity:999999)]);
        Test("default raw and opt-in candidate label with source identity",()=>{var names=new CatalogProviderNames();names.SetProvider(new MhriceCatalogProvider(Make("SYNTHETIC external"),"SYNTHETIC-HASH"));Assert(names.Label(CatalogNamespace.Item,0x04000031)=="Item 67108913");names.ShowUnverifiedCandidates=true;Assert(names.Label(CatalogNamespace.Item,0x04000031).Contains("SYNTHETIC external [unverified candidate]"));Assert(names.Describe(GameCatalogKind.Item,0x04000031).Contains("UNVERIFIED_MAPPING")&&names.Describe(GameCatalogKind.Item,0x04000031).Contains("SYNTHETIC-HASH"));names.ShowUnverifiedCandidates=false;Assert(names.Label(CatalogNamespace.Item,0x04000031)=="Item 67108913");});
        Test("candidate precedence and locale are display-only",()=>{string locale="en";var names=new CatalogProviderNames(()=>locale){ShowUnverifiedCandidates=true};names.SetProvider(new MhriceCatalogProvider(Make("EXTERNAL"),"synthetic"));names.SetProvider(new LocalGameCatalogProvider(Make("LOCAL")));Assert(names.Label(CatalogNamespace.Item,0x04000031).StartsWith("LOCAL"));locale="zh-CN";Assert(names.Label(CatalogNamespace.Item,0x04000031).Contains("未验证候选"));Assert(names.ResolveAll(GameCatalogKind.Item,0x04000031).All(m=>m.MappingStatus!=CatalogMappingStatus.VERIFIED_NS_MAPPING));});
        Test("verified NS status cannot be issued by current provider API",()=>{bool blocked=false;try{_=new CatalogMapping(Make("TEST").Entries[0],"synthetic",CatalogProviderSource.Local,CatalogMappingStatus.VERIFIED_NS_MAPPING,"self claimed");}catch(NotSupportedException){blocked=true;}Assert(blocked);});
        Test("unmatched IDs stay numeric and mappings never grant range permission",()=>{var names=new CatalogProviderNames(){ShowUnverifiedCandidates=true};names.SetProvider(new MhriceCatalogProvider(Make("TEST"),"test"));Assert(names.Label(CatalogNamespace.Item,999)=="Item 999");string dir=Path.Combine(Directory.GetCurrentDirectory(),"synthetic-run-provider-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string file=Path.Combine(dir,"sample.bin");File.WriteAllBytes(file,WorkspaceSyntheticSamples.Slot());var workspace=new EditorWorkspace();workspace.Open(file);var domain=new DomainEditor(workspace);string digest=workspace.Document!.Digest;_=names.Label(CatalogNamespace.Item,domain.Inventory()[0].Id!.Value);bool blocked=false;try{domain.SetItemQuantity(0,10000);}catch(InvalidOperationException){blocked=true;}Assert(blocked&&workspace.StagedCount==0&&workspace.Document.Digest==digest);});
        Test("reviewed MHRice resource loads as unverified candidate names only",()=>{var resource=GameCatalog.LoadDirectory(Path.Combine(Directory.GetCurrentDirectory(),"data","mhrice"));Assert(resource.Entries.Count==7675);var counts=resource.Entries.GroupBy(e=>e.Kind).ToDictionary(g=>g.Key,g=>g.Count());Assert(counts[GameCatalogKind.Item]==1771&&counts[GameCatalogKind.Skill]==147&&counts[GameCatalogKind.Decoration]==244&&counts[GameCatalogKind.Weapon]==3953&&counts[GameCatalogKind.Armor]==1560);var entry=resource.Entries.First(e=>e.Kind==GameCatalogKind.Item);string language="en";var names=new CatalogProviderNames(()=>language);names.SetProvider(new MhriceCatalogProvider(resource,GameValidation.Hash(File.ReadAllBytes(Path.Combine(Directory.GetCurrentDirectory(),"data","mhrice","catalog.json")))));Assert(names.Label(CatalogNamespace.Item,entry.Id)==$"Item {entry.Id}");names.ShowUnverifiedCandidates=true;Assert(names.Label(CatalogNamespace.Item,entry.Id).Contains(entry.Names["en"]));language="zh-CN";Assert(names.Label(CatalogNamespace.Item,entry.Id).Contains(entry.Names["zh-CN"]));Assert(names.ResolveAll(GameCatalogKind.Item,entry.Id).All(m=>m.MappingStatus==CatalogMappingStatus.UNVERIFIED_MAPPING));names.ShowUnverifiedCandidates=false;Assert(names.Label(CatalogNamespace.Item,entry.Id)==$"Item {entry.Id}");});
        File.WriteAllText("test-results-providers.json",JsonSerializer.Serialize(new{executedAtUtc=DateTimeOffset.UtcNow,scope="SYNTHETIC provider gating only; no actual game-name verification",checks,failures},new JsonSerializerOptions(){WriteIndented=true}));Console.WriteLine($"Provider groups={checks.Count}; failures={failures}");return failures==0?0:1;
    }
}


